const Base = CommonMathJaxPagellaFontMixin(SvgFontData);
class MathJaxPagellaFont extends Base {
    constructor(options = {}) {
        super(options);
        const CLASS = this.constructor;
        for (const variant of Object.keys(this.variant)) {
            this.variant[variant].cacheID = 'GP-' + (CLASS.variantCacheIds[variant] || 'N');
        }
    }
}
MathJaxPagellaFont.NAME = 'MathJaxPagella';
MathJaxPagellaFont.OPTIONS = Object.assign(Object.assign({}, Base.OPTIONS), { dynamicPrefix: '@mathjax/mathjax-pagella-font/js/svg/dynamic' });
MathJaxPagellaFont.defaultDelimiters = delimiters;
